import{_ as a,c as o,o as t,aj as c}from"./chunks/framework.B-K7myP5.js";const u=JSON.parse('{"title":"配置信息","frontmatter":{"title":"配置信息","createTime":"2025/01/17 19:27:31","permalink":"/docs/composer/config.html","lastUpdated":"2026-01-22","tags":[],"link":"/docs/composer/教程/config","layout":"doc","sidebar":true,"aside":true,"prev":{"text":"扩展包源仓库","link":"/docs/composer/教程/repositories"},"next":{"text":"社区","link":"/docs/composer/教程/community"}},"headers":[],"params":{"pkg":"composer/教程/config","sidebar":[{"text":"常见问题","items":[{"text":"如何为我的框架自定义一个扩展包安装目录？","link":"/docs/composer/index"},{"text":"如何使用脚本安装 Composer？","link":"/docs/composer/常见问题/to-install-composer-programmatically"},{"text":"使用 root 用户来安装扩展包是否安全？如何安全地安装未认证渠道的扩展包？","link":"/docs/composer/常见问题/to-install-untrusted-packages-safely"},{"text":"我应该将 vendor 目录加入版本控制吗？","link":"/docs/composer/常见问题/i-commit-the-dependencies-in-my-vendor-directory"},{"text":"Composer 使用的是什么版本命名规范？","link":"/docs/composer/常见问题/version-numbering-system-does-composer-itself-use"},{"text":"为什么限制版本是最佳实践？","link":"/docs/composer/常见问题/are-unbound-version-constraints-a-bad-idea"},{"text":"为何版本限制与对比符、通配符配合使用是个糟糕的行为？","link":"/docs/composer/常见问题/are-version-constraints-combining-comparisons-and-wildcards-a-bad-idea"},{"text":"为什么 Composer 不递归加载代码库？","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively"}]},{"text":"官方文章","items":[{"text":"分支别名","link":"/docs/composer/官方文章/aliases"},{"text":"版本限制","link":"/docs/composer/官方文章/versions"},{"text":"自动加载器优化","link":"/docs/composer/官方文章/optimization"},{"text":"自定义安装器","link":"/docs/composer/官方文章/installers"},{"text":"使用 Satis 处理私有仓库","link":"/docs/composer/官方文章/private-packages-with-satis"},{"text":"HTTP 基础认证","link":"/docs/composer/官方文章/basic-authentication"},{"text":"创建 Composer 插件","link":"/docs/composer/官方文章/plugins"},{"text":"事件和自定义脚本","link":"/docs/composer/官方文章/scripts"},{"text":"故障排除","link":"/docs/composer/官方文章/troubleshooting"},{"text":"可执行二进制文件","link":"/docs/composer/官方文章/binaries"}]},{"text":"教程","items":[{"text":"简介","link":"/docs/composer/教程/intro"},{"text":"基本使用","link":"/docs/composer/教程/basic-usage"},{"text":"创建扩展包","link":"/docs/composer/教程/libraries"},{"text":"Composer 命令的使用","link":"/docs/composer/教程/cli"},{"text":"json 完全解析","link":"/docs/composer/教程/schema"},{"text":"扩展包源仓库","link":"/docs/composer/教程/repositories"},{"text":"配置信息","link":"/docs/composer/教程/config"},{"text":"社区","link":"/docs/composer/教程/community"}]}],"versions":[]},"relativePath":"docs/composer/教程/config.md","filePath":"docs/[pkg].md"}'),r={name:"docs/composer/教程/config.md"};function s(i,e,d,l,n,h){return t(),o("div",null,[...e[0]||(e[0]=[c(`<h1 id="config" tabindex="-1">Config <a class="header-anchor" href="#config" aria-label="Permalink to “Config”">​</a></h1><p>本章将介绍 <a href="https://github.com/composer/composer/blob/master/doc/04-schema.md" target="_blank" rel="noreferrer"><code>composer.json</code></a> 中配置相关的信息。</p><h2 id="process-timeout-请求过程超时设置" tabindex="-1"><code>process-timeout</code> 请求过程超时设置 <a class="header-anchor" href="#process-timeout-请求过程超时设置" aria-label="Permalink to “process-timeout 请求过程超时设置”">​</a></h2><p>默认请求超时时间设置为 <code>300</code> 秒 ，像使用 <code>Git</code> 进行 Clone 操作时一样，<code>Composer</code> 可以在请求超时之前一直运行，直到完成安装。如果你的网络速度不够快，或者要加载的内容比较多，可以把超时时间设置的高一些。</p><h2 id="use-include-path-使用包含路径设置" tabindex="-1"><code>use-include-path</code> 使用包含路径设置 <a class="header-anchor" href="#use-include-path-使用包含路径设置" aria-label="Permalink to “use-include-path 使用包含路径设置”">​</a></h2><p>默认设置 <code>false</code>，如果设置成 <code>true</code>, <code>Composer</code> 自动加载器会自动查找 <code>PHP</code> 路径中包含的类。</p><h2 id="preferred-install-安装首选项设置" tabindex="-1"><code>preferred-install</code> 安装首选项设置 <a class="header-anchor" href="#preferred-install-安装首选项设置" aria-label="Permalink to “preferred-install 安装首选项设置”">​</a></h2><p>默认设置 <code>auto</code> 模式 ，可以设置为 <code>source</code>, <code>dist</code> 或者 <code>auto</code> 模式。这个选项允许你将 <code>Composer </code> 设置为自己喜欢的模式。要进行更精确的安装首选项设置，可以使用哈希模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;config&quot;: {</span></span>
<span class="line"><span>        &quot;preferred-install&quot;: {</span></span>
<span class="line"><span>            &quot;my-organization/stable-package&quot;: &quot;dist&quot;,</span></span>
<span class="line"><span>            &quot;my-organization/*&quot;: &quot;source&quot;,</span></span>
<span class="line"><span>            &quot;partner-organization/*&quot;: &quot;auto&quot;,</span></span>
<span class="line"><span>            &quot;*&quot;: &quot;dist&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><blockquote><p>请注意：设置选项模式使用的顺序很重要。精确的设置模式应该在宽泛的设置模式之前使用，精确的模式设置才会生效。在全局和包设置中，当混合使用字符串与哈希进行设置时，字符串设置项将转换为 <code>*</code> 模式。</p></blockquote><h2 id="store-auths" tabindex="-1">store-auths <a class="header-anchor" href="#store-auths" aria-label="Permalink to “store-auths”">​</a></h2><p>认证弹框后采取的动作，有三个选项：</p><ul><li><code>true</code> 永远存储认证信息；</li><li><code>false</code> 不存储认证信息；</li><li><code>&quot;prompt&quot;</code> 每一次都会要求重新验证，此为默认项。</li></ul><h2 id="github-protocols" tabindex="-1">github-protocols <a class="header-anchor" href="#github-protocols" aria-label="Permalink to “github-protocols”">​</a></h2><p>默认为 <code>[&quot;https&quot;, &quot;ssh&quot;, &quot;git&quot;]</code>。从 github.com 克隆时使用的协议优先级清单，<code>git</code> 协议不是加密传输，所以只有当 <a href="https://github.com/composer/composer/blob/master/doc/06-config.md#secure-http" target="_blank" rel="noreferrer">secure-http</a>  项设置为关闭时，才会优先使用 <code>git</code> 协议进行克隆。如果你想设置远程 Push URL 使用 HTTPS 协议而非 SSH (<code>git@github.com:...</code>) 协议，你可以只设置 <code>[&quot;https&quot;]</code> ，这样 Composer 就会停止重写 Push URL 为 SSH 协议。</p><h2 id="github-oauth" tabindex="-1">github-oauth <a class="header-anchor" href="#github-oauth" aria-label="Permalink to “github-oauth”">​</a></h2><p>一个域名和 Oauth Keys 的列表。 例如：使用 <code>{&quot;github.com&quot;: &quot;oauthtoken&quot;}</code> 作为此选项的值， 将使用 <code>oauthtoken</code> 来访问 github 上的私人仓库，并绕过基于 IP 的 API 使用频率。 <a href="https://github.com/composer/composer/blob/master/doc/articles/troubleshooting.md#api-rate-limit-and-oauth-tokens" target="_blank" rel="noreferrer">点此获取</a> 关于如何获取 GitHub 的 OAuth token。</p><h2 id="gitlab-oauth" tabindex="-1">gitlab-oauth <a class="header-anchor" href="#gitlab-oauth" aria-label="Permalink to “gitlab-oauth”">​</a></h2><p>一个域名和 Oauth Keys 的列表。 例如：使用 <code>{&quot;gitlab.com&quot;: &quot;oauthtoken&quot;}</code> 作为此选项的值， 将使用 <code>oauthtoken</code> 来访问 Gitlab 上的私人仓库。请注意：如果你的代码不是托管在 gitlab.com 上的，你还需要配置这个参数 ——  <a href="https://github.com/composer/composer/blob/master/doc/06-config.md#gitlab-domains" target="_blank" rel="noreferrer"><code>gitlab-domains</code></a> 。</p><h2 id="gitlab-token" tabindex="-1">gitlab-token <a class="header-anchor" href="#gitlab-token" aria-label="Permalink to “gitlab-token”">​</a></h2><p>一个域名和 Private Token 的列表。例如： 使用  <code>{&quot;gitlab.com&quot;: &quot;privatetoken&quot;}</code> 作为这个选项的值，将使用 <code>privatetoken</code> 来访问 Gitlab 上的私人仓库。请注意: 如果你的代码不是托管在 gitlab.com 上的，你还必须指定这个参数 ——  <a href="https://github.com/composer/composer/blob/master/doc/06-config.md#gitlab-domains" target="_blank" rel="noreferrer"><code>gitlab-domains</code></a> 。</p><h2 id="disable-tls" tabindex="-1">disable-tls <a class="header-anchor" href="#disable-tls" aria-label="Permalink to “disable-tls”">​</a></h2><p>默认为 <code>false</code>。如果设置为<code>true</code>，所有的 HTTPS URL 将会被替换成 HTTP，并且网络层加密将不被使用。开启这个选项会有安全风险，所以不建议开启，更好地办法是在 php.ini 中开启 php_openssl 扩展。</p><h2 id="secure-http" tabindex="-1">secure-http <a class="header-anchor" href="#secure-http" aria-label="Permalink to “secure-http”">​</a></h2><p>默认为 <code>true</code> 。如果设置为 <code>true</code>，只有 HTTPS URL 才被允许在 Composer 中使用，如果你真的确定需要使用 HTTP 来访问一些东西，你可以关闭它，但使用 <a href="https://letsencrypt.org/" target="_blank" rel="noreferrer">Let&#39;s Encrypt</a> 这样的供应商来获得一个免费的 SSL 证书会是一个更好地选择。</p><h2 id="bitbucket-oauth" tabindex="-1">bitbucket-oauth <a class="header-anchor" href="#bitbucket-oauth" aria-label="Permalink to “bitbucket-oauth”">​</a></h2><p>一个域名和使用者名称的列表。比如使用 <code>{&quot;bitbucket.org&quot;: {&quot;consumer-key&quot;: &quot;myKey&quot;, &quot;consumer-secret&quot;: &quot;mySecret&quot;}}</code>。 <a href="https://confluence.atlassian.com/bitbucket/oauth-on-bitbucket-cloud-238027431.html" target="_blank" rel="noreferrer">详见</a> 了解如何在 BitBucket 创建一个使用者。</p><h2 id="cafile" tabindex="-1">cafile <a class="header-anchor" href="#cafile" aria-label="Permalink to “cafile”">​</a></h2><p>本地文件系统中认证证书的位置。在 PHP 5.6+ 中你应该在 php.ini 通过 openssl.cafile 来设置，尽管在 PHP 5.6+ 中这会被自动获取。</p><h2 id="capath" tabindex="-1">capath <a class="header-anchor" href="#capath" aria-label="Permalink to “capath”">​</a></h2><p>如果证书文件未指定或在那个位置没找到证书，则系统会在 capath 所指定的文件中查找一个合适的证书。capath 必须是一个存在被正确哈希加密证书的目录。</p><h2 id="http-basic" tabindex="-1">http-basic <a class="header-anchor" href="#http-basic" aria-label="Permalink to “http-basic”">​</a></h2><p>一个域名和存储验证所需用户名密码的列表。例如使用 <code>{&quot;example.org&quot;: {&quot;username&quot;: &quot;alice&quot;, &quot;password&quot;: &quot;foo&quot;}}</code> 作为它的值，则会让 Composer 用指定的用户名密码去验证 example.org。</p><blockquote><p>注意：与验证相关的设置项比如 <code>http-basic</code> 和 <code>github-oauth</code> 也可以定义在 <code>auth.json</code> 文件中，脱离 <code>composer.json</code>。通过这样你可以让 Git 忽略它，并且每个开发者可以存储他们自己的验证凭据。</p></blockquote><h2 id="platform" tabindex="-1">platform <a class="header-anchor" href="#platform" aria-label="Permalink to “platform”">​</a></h2><p>让你伪装平台扩展包（PHP 和 其扩展）以便于模拟生产环境以及在设置中定义你的目标平台。例如：<code>{&quot;php&quot;: &quot;7.0.3&quot;, &quot;ext-something&quot;: &quot;4.0.3&quot;}</code>。</p><h2 id="vendor-dir" tabindex="-1">vendor-dir <a class="header-anchor" href="#vendor-dir" aria-label="Permalink to “vendor-dir”">​</a></h2><p>默认是 <code>vendor</code>。你也可以在一个不同的目录安装所需依赖。<code>$HOME</code> 和 <code>~</code> 在 vendor 和下面所有的 <code>*-dir</code>目录中会被替换成你的 HOME 目录。</p><h2 id="bin-dir" tabindex="-1">bin-dir <a class="header-anchor" href="#bin-dir" aria-label="Permalink to “bin-dir”">​</a></h2><p>默认是 <code>vendor/bin</code>。如果一个项目包含可执行文件，那它们会在这个目录中做符号链接。</p><h2 id="data-dir" tabindex="-1">data-dir <a class="header-anchor" href="#data-dir" aria-label="Permalink to “data-dir”">​</a></h2><p>在 WIndows 中默认是 <code>C:\\Users\\&lt;user&gt;\\AppData\\Roaming\\Composer</code>，在遵守 XDG 目录定义的 unix 系统中是 <code>$XDG_DATA_HOME/composer</code>，在其他 unix 系统中则会是 <code>$home</code>。现在它只用来存储旧版本的 composer.phar 文件来以防回滚。详见 <a href="https://github.com/composer/composer/blob/master/doc/03-cli.md#composer-home" target="_blank" rel="noreferrer">COMPOSER_HOME</a>。</p><h2 id="cache-dir" tabindex="-1">cache-dir <a class="header-anchor" href="#cache-dir" aria-label="Permalink to “cache-dir”">​</a></h2><p>在 WIndows 中默认是 <code>C:\\Users\\&lt;user&gt;\\AppData\\Local\\Composer</code>，在遵守 XDG 目录定义的 unix 系统中是 <code>$XDG_CACHE_HOME/composer</code>，在其他 unix 系统中则会是 <code>$home/cache</code>。存储 Composer 用到的所有缓存文件。详见 <a href="https://github.com/composer/composer/blob/master/doc/03-cli.md#composer-home" target="_blank" rel="noreferrer">COMPOSER_HOME</a>。</p><h2 id="cache-files-dir" tabindex="-1">cache-files-dir <a class="header-anchor" href="#cache-files-dir" aria-label="Permalink to “cache-files-dir”">​</a></h2><p>默认是 <code>$cache-dir/files</code>。存储所有扩展包的 ZIP 压缩包。</p><h2 id="cache-repo-dir" tabindex="-1">cache-repo-dir <a class="header-anchor" href="#cache-repo-dir" aria-label="Permalink to “cache-repo-dir”">​</a></h2><p>默认是 <code>$cache-dir/repo</code>。存储 <code>composer</code> 类型仓库的元数据和 <code>svn</code>, <code>fossil</code>, <code>github</code>, <code>bitbucket</code> 类型仓库的 VCS 仓库。</p><h2 id="cache-vcs-dir" tabindex="-1">cache-vcs-dir <a class="header-anchor" href="#cache-vcs-dir" aria-label="Permalink to “cache-vcs-dir”">​</a></h2><p>默认是 <code>$cache-dir/vcs</code>。存储所有 <code>git</code>/<code>hg</code> 类型仓库所克隆的文件以加快安装速度。</p><h2 id="cache-files-ttl" tabindex="-1">cache-files-ttl <a class="header-anchor" href="#cache-files-ttl" aria-label="Permalink to “cache-files-ttl”">​</a></h2><p>默认是 <code>15552000</code> （6个月）。Composer 会缓存它下载的所有扩展包构建的文件 (zip, tar, ..) 。默认6个月不使用就会被清空。此设置项允许你更改这个过期时间（秒为单位）或设为0来完全禁用。</p><h2 id="cache-files-maxsize" tabindex="-1">cache-files-maxsize <a class="header-anchor" href="#cache-files-maxsize" aria-label="Permalink to “cache-files-maxsize”">​</a></h2><p>默认是 <code>300MiB</code>。 Composer 会缓存它下载的所有扩展包构建的文件 (zip, tar, ..) 。这是它在定期执行垃圾回收时允许缓存文件占用的最大空间。更旧或是不经常使用的缓存会被清除。</p><h2 id="bin-compat" tabindex="-1">bin-compat <a class="header-anchor" href="#bin-compat" aria-label="Permalink to “bin-compat”">​</a></h2><p>默认是 <code>auto</code>。决定了可执行文件安装时需要的兼容性。如果设为 <code>auto</code>，则在 Windows 中只会安装 .bat 文件。如果设为 <code>full</code> 那么除了 .bat，unix 系统所需要的脚本文件也会被安装。这主要是为了处理执行 Composer 和项目运行所在系统不一致的情况。</p><h2 id="prepend-autoloader" tabindex="-1">prepend-autoloader <a class="header-anchor" href="#prepend-autoloader" aria-label="Permalink to “prepend-autoloader”">​</a></h2><p>默认是 <code>true</code>。如果设为 <code>false</code>，Composer 的自动加载器则不会预载入到已存在的自动加载器中。这有时可以用来修复一些因与其他加载器共用导致的一些问题。</p><h2 id="autoloader-suffix" tabindex="-1">autoloader-suffix <a class="header-anchor" href="#autoloader-suffix" aria-label="Permalink to “autoloader-suffix”">​</a></h2><p>默认是 <code>null</code>。会用做 Composer 自动加载器后缀的字符串。如果为空，则会生成一组随机字符串。</p><h2 id="optimize-autoloader" tabindex="-1">optimize-autoloader <a class="header-anchor" href="#optimize-autoloader" aria-label="Permalink to “optimize-autoloader”">​</a></h2><p>默认是 <code>false</code>。如果设为 <code>true</code>，则总会在生成自动加载器时进行优化。</p><h2 id="sort-packages" tabindex="-1">sort-packages <a class="header-anchor" href="#sort-packages" aria-label="Permalink to “sort-packages”">​</a></h2><p>默认是 <code>false</code>。如果设为 <code>true</code>，执行 <code>require</code> 命令时会始终保持 <code>composer.json</code> 文件中的扩展包名按照字母顺序排列。</p><h2 id="classmap-authoritative" tabindex="-1">classmap-authoritative <a class="header-anchor" href="#classmap-authoritative" aria-label="Permalink to “classmap-authoritative”">​</a></h2><p>默认是 <code>false</code>。如果设为 <code>true</code>，Composer 自动加载器只会载入 classmap 中的类。此项会启用 <code>optimize-autoloader</code>。</p><h2 id="apcu-autoloader" tabindex="-1">apcu-autoloader <a class="header-anchor" href="#apcu-autoloader" aria-label="Permalink to “apcu-autoloader”">​</a></h2><p>默认是 <code>false</code>。如果设为 <code>true</code>，Composer 自动加载器会检查 APCu，并且当扩展被启用时，使用它来缓存找到和未找到的类。</p><h2 id="github-domains" tabindex="-1">github-domains <a class="header-anchor" href="#github-domains" aria-label="Permalink to “github-domains”">​</a></h2><p>默认是 <code>[&quot;github.com&quot;]</code>。一个在 gitHub 模式中使用的域名列表。GitHub Enterprise 可能会用到此项。</p><h2 id="github-expose-hostname" tabindex="-1">github-expose-hostname <a class="header-anchor" href="#github-expose-hostname" aria-label="Permalink to “github-expose-hostname”">​</a></h2><p>默认是 <code>true</code>。如果设为 <code>false</code>，为访问 Github API 创建的 OAuth 令牌会有一个日期而不是主机名。</p><h2 id="gitlab-domains" tabindex="-1">gitlab-domains <a class="header-anchor" href="#gitlab-domains" aria-label="Permalink to “gitlab-domains”">​</a></h2><p>默认是 <code>[&quot;gitlab.com&quot;]</code>。一个 Gitlab 服务器的域名列表。如果你使用 <code>gitlab</code> 仓库类型时可能会用到此项。</p><h2 id="notify-on-install" tabindex="-1">notify-on-install <a class="header-anchor" href="#notify-on-install" aria-label="Permalink to “notify-on-install”">​</a></h2><p>默认是 <code>true</code>。Composer 允许仓库定义一个通知 URL，以便于在基于此仓库的扩展包被安装时接收通知。此项允许你禁用此行为。</p><h2 id="discard-changes" tabindex="-1">discard-changes <a class="header-anchor" href="#discard-changes" aria-label="Permalink to “discard-changes”">​</a></h2><p>默认是 <code>false</code> 并且可以被设为 <code>true</code>，<code>false</code> 或 <code>&quot;stash&quot;</code>。此项允许你设置在升级过程中发生冲突时的默认行为。<code>true</code> 会放弃 vendors 中的更改，而 <code>&quot;stash&quot;</code> 尝试着去暂存以便于恢复。如果你的 CI 服务器或部署脚本可能会更改 vendors，那么可以使用该设置。</p><h2 id="archive-format" tabindex="-1">archive-format <a class="header-anchor" href="#archive-format" aria-label="Permalink to “archive-format”">​</a></h2><p>默认是 <code>tar</code>。Composer 允许你设置在工作流需要创建特定格式压缩包时的默认压缩格式。</p><h2 id="archive-dir" tabindex="-1">archive-dir <a class="header-anchor" href="#archive-dir" aria-label="Permalink to “archive-dir”">​</a></h2><p>默认是 <code>.</code>。Composer 允许你设置在工作流需要创建特定格式压缩包时的默认压缩文件存储路径。也为了模块间的开发变得更加容易。</p><p>举个例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;config&quot;: {</span></span>
<span class="line"><span>        &quot;archive-dir&quot;: &quot;/home/user/.composer/repo&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="htaccess-protect" tabindex="-1">htaccess-protect <a class="header-anchor" href="#htaccess-protect" aria-label="Permalink to “htaccess-protect”">​</a></h2><p>默认是 <code>true</code>。如果设为 <code>false</code>，Composer 不会在 COMPOSER_HOME、cache、和数据目录创建 <code>.htaccess</code> 文件。</p>`,86)])])}const m=a(r,[["render",s]]);export{u as __pageData,m as default};
